import java.util.*;

class Solution {
    public int[] findOrder(int numCourses, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());
        int[] indegree = new int[numCourses];
        for (int[] p : prerequisites) {
            adj.get(p[1]).add(p[0]);
            indegree[p[0]]++;
        }

        boolean[] removed = new boolean[numCourses];
        int[] order = new int[numCourses];
        int pos = 0;

        while (true) {
            List<Integer> batch = new ArrayList<>();
            for (int i = 0; i < numCourses; i++) {
                if (!removed[i] && indegree[i] == 0) batch.add(i);
            }
            if (batch.isEmpty()) break;
            for (int u : batch) {
                removed[u] = true;
                order[pos++] = u;
                for (int v : adj.get(u)) indegree[v]--;
            }
        }

        return pos == numCourses ? order : new int[0];
    }
}

import java.util.*;

class Solution {
    private List<List<Integer>> adj;
    private int[] color;
    private List<Integer> order;

    public int[] findOrder(int numCourses, int[][] prerequisites) {
        adj = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());
        for (int[] p : prerequisites) adj.get(p[1]).add(p[0]);

        color = new int[numCourses];
        order = new ArrayList<>();

        for (int i = 0; i < numCourses; i++) {
            if (color[i] == 0 && !dfs(i)) return new int[0];
        }
        Collections.reverse(order);

        int[] result = new int[numCourses];
        for (int i = 0; i < numCourses; i++) result[i] = order.get(i);
        return result;
    }

    private boolean dfs(int u) {
        color[u] = 1;
        for (int v : adj.get(u)) {
            if (color[v] == 1) return false;
            if (color[v] == 0 && !dfs(v)) return false;
        }
        color[u] = 2;
        order.add(u);
        return true;
    }
}

import java.util.*;

class Solution {
    public int[] findOrder(int numCourses, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());
        int[] indegree = new int[numCourses];
        for (int[] p : prerequisites) {
            adj.get(p[1]).add(p[0]);
            indegree[p[0]]++;
        }

        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < numCourses; i++) {
            if (indegree[i] == 0) queue.add(i);
        }

        int[] order = new int[numCourses];
        int pos = 0;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            order[pos++] = u;
            for (int v : adj.get(u)) {
                if (--indegree[v] == 0) queue.add(v);
            }
        }

        return pos == numCourses ? order : new int[0];
    }
}
